import {mountNewsCompanies} from './news-companies.js';
import {escapeHtml as esc} from './components.js';
import {safeComparisonUrl} from './comparison-model.js';
const stateLabel={QUEUED:'대기',RUNNING:'실행 중',PARTIAL:'부분 완료',COMPLETE:'완료',RETRY_WAIT:'재시도 대기',BUDGET_WAIT:'예산 대기',MANUAL_REVIEW:'확인 필요',SECURITY_BLOCKED:'보안 차단',PAUSED:'중지',AVAILABLE:'확보',EXTRACTION_UNRESOLVED:'추출 미해결',NOT_COLLECTED:'수집 전',FETCH_FAILED:'접근 실패'};
const axis={DESCRIPTION:'사업 설명',PRODUCT:'제품별 매출',BUSINESS_SEGMENT:'사업부 매출',END_MARKET:'전방시장',GEOGRAPHY:'지역별 매출',DOMESTIC_EXPORT:'수출·내수',CUSTOMER:'고객별 매출',SINGLE_QUARTER:'단일 분기',TTM:'최근 12개월'};
const jobKind={LATEST_PROFILE:'최신 사업',REVENUE_STRUCTURE:'매출 구조',COMPARATIVE_PERIODS:'비교 기간',HISTORY:'과거 이력',REPORT:'공시 원문'};
function performanceLine(run){const p=JSON.parse(run.payload||'{}');return `작업자 ${p.peakRssMB?Number(p.peakRssMB).toFixed(1)+' MB':'미측정'} · 처리 ${p.lastBatchMs?(p.lastBatchMs/1000).toFixed(2)+'초':'미측정'} · AI ${p.aiCalls||0}회 / 검색 ${p.searchCalls||0}회`;}
function mountBusinessAdmin(root){
 const life=new AbortController();let data=null,message='',offset=0,timer=null;
 root.innerHTML='<div class="page-heading"><div><div class="eyebrow">COMPANY BUSINESS & REVENUE</div><h1>기업 사업정보</h1><p>저장된 제품·사업과 매출 구성을 찾아보세요.</p></div></div><section class="surface"><form class="bp-search-form"><label>사업·제품 <input name="q" placeholder="전력기기, 검사장비 등" required></label><label>시장 <select name="market"><option value="">국내·미국</option><option value="KR">국내</option><option value="US">미국</option></select></label><label>최소 공시 비중 <input name="minShare" type="number" min="0" max="100" placeholder="미설정"> %</label><button>검색</button></form><p class="bp-note">숫자 조건은 표시된 원문 항목에만 적용합니다. 미확인 비중을 0%로 취급하지 않습니다.</p><div class="bp-search-results" aria-live="polite"></div></section><section class="surface bp-admin"><h2>구축 진행</h2><p>관리자 권한을 확인하고 있습니다.</p></section>';
 const admin=root.querySelector('.bp-admin');
 async function request(body){const r=await fetch('/api/business-profiles/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:life.signal}),d=await r.json();if(!r.ok)throw Error(d.message);return d;}
 function render(){const u=data.universe||{};admin.innerHTML=`<div class="research-heading"><h2>구축 진행 · 관리자</h2><button data-bpd="refresh">새로고침</button></div><p role="status">${esc(message)}</p><div class="bp-admin-stats"><p>대상 기업 <strong>${u.targetCompanies??'등록 전'}</strong></p><p>대상 종목 <strong>${u.eligibleInstruments??'등록 전'}</strong></p><p>중복 연결 <strong>${u.duplicateLinks??0}</strong></p><p>식별 보류 <strong>${u.identityHold??0}</strong></p></div><p class="bp-note">${esc(u.scope||'현재 종목 Master를 읽어 기업별 작업을 등록합니다. 등록만으로 외부 수집을 시작하지 않습니다.')}</p><button data-bpd="register">전체 기업 작업 등록</button><p>${Object.entries(u.excluded||{}).map(([k,v])=>esc(k)+': '+v).join(' · ')}</p><h3>작업 상태</h3><p>${data.states.map(s=>`${stateLabel[s.state]||esc(s.state)} ${s.count}`).join(' · ')||'등록된 작업 없음'}</p><form class="bp-batch-form"><label>수집 경로 <select name="mode"><option value="CACHE_ONLY">저장 자료만</option><option value="OFFICIAL">공식 자료 보충</option></select></label><label>이번 실행 기업/작업 수 <input name="companyLimit" type="number" value="6" min="1" max="25"></label><label>외부 호출 총예산 <input name="requestLimit" type="number" value="0" min="0" max="100"></label><button>제한 배치 만들기</button></form><p class="bp-note">배치를 만든 뒤 시작 버튼을 눌러야 실행됩니다. 공식 자료 보충은 기업당 최대 18회를 예약합니다. AI·검색은 사용하지 않습니다.</p><div class="bp-run-list">${data.runs.map(r=>`<article><strong>${stateLabel[r.state]||esc(r.state)} · ${esc(r.mode)}</strong><p>처리 ${r.processed}건 · 호출 ${r.used_requests}/${r.request_limit} · 예약 ${r.reserved_requests}</p><small>${esc(performanceLine(r))}</small><br><button data-bpd="start" data-id="${esc(r.id)}">시작·재개</button> <button data-bpd="pause" data-id="${esc(r.id)}">중지</button></article>`).join('')}</div><details open><summary>항목별 확보율</summary><p>작업 완료율과 자료 확보율은 다릅니다.</p><p class="bp-note">전체 대상 기업 수를 분모로 표시합니다. 미시도 기업은 수집 전이며, 확보된 구성만으로 전체 공개 항목을 채웠다고 판단하지 않습니다.</p><div class="bp-coverage">${data.coverage.map(c=>`<p>${esc(axis[c.dimension]||c.dimension)} · ${stateLabel[c.state]||esc(c.state)} <strong>${c.companies}개 기업</strong> (${u.targetCompanies?(c.companies/u.targetCompanies*100).toFixed(2):'0'}%) / 관측값 ${c.observations}건</p>`).join('')||'<p>아직 집계된 자료가 없습니다.</p>'}</div></details><details><summary>최근 작업 · 출처와 미확인 항목</summary>${data.jobs.map(j=>`<p><a href="/stock/${j.asset_id.startsWith('KR:')?'KR':'US'}/${encodeURIComponent(j.symbol)}?tab=company">${esc(j.name)} ${esc(j.symbol)}</a> · ${esc(jobKind[j.purpose]||j.purpose)} · ${stateLabel[j.state]||esc(j.state)} · ${esc(j.error_code||'')}<br><small>${esc(j.updated_at)}</small>${['PARTIAL','MANUAL_REVIEW','RETRY_WAIT','BUDGET_WAIT'].includes(j.state)?` <button data-bpd="retry" data-id="${esc(j.id)}">재시도 등록</button>`:''}</p>`).join('')}<button data-bpd="previous">이전</button> <button data-bpd="next">다음</button></details>${data.provider?`<details><summary>FMP 제공 범위</summary>${data.provider.results.map(r=>`<p>${esc(r.symbol)} · ${esc(r.path.split('/').at(-1))} · ${esc(r.requestedPeriod)}: ${esc(r.status)} · HTTP ${r.httpStatus??'미확인'}</p>`).join('')}</details>`:''}`;}
 async function load(){try{const r=await fetch('/api/business-profiles/admin?offset='+offset,{signal:life.signal});if(r.status===403){admin.innerHTML='<h2>구축 진행</h2><p>관리자 인증이 필요합니다.</p>';return;}if(!r.ok)throw Error();data=await r.json();render();clearTimeout(timer);if(data.runs.some(r=>r.state==='RUNNING'))timer=setTimeout(load,3000);}catch{if(!life.signal.aborted)admin.innerHTML='<h2>구축 진행</h2><p>저장소에 연결하지 못했습니다. 새로고침해 주세요.</p>';}}
 root.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.matches('.bp-search-form')){const target=root.querySelector('.bp-search-results');try{const r=await fetch('/api/business-profiles/search?'+new URLSearchParams(f),{signal:life.signal}),v=await r.json();target.innerHTML=(v.items||[]).map(x=>`<article><h3><a href="/stock/${esc(x.market)}/${encodeURIComponent(x.ticker)}?tab=company">${esc(x.name)} · ${esc(x.ticker)}</a></h3><p>${esc(x.businessSummary?.slice(0,200)||x.products.join(' · '))}</p>${x.matches.filter(m=>m.dimension!=='DESCRIPTION').map(m=>`<p>${esc(m.label)} · ${m.percent===null||m.percent===undefined?'비중 미확인':esc(Number(m.percent).toLocaleString('ko-KR',{maximumFractionDigits:2}))+'%'} · ${esc(m.period?.label||'기간 미확인')}</p>`).join('')}</article>`).join('')||'<p>저장된 사업 근거와 일치하는 기업이 없습니다.</p>';}catch{target.textContent='검색 연결 오류 · 다시 시도해 주세요.';}}else{try{await request({action:'create',mode:f.get('mode'),companyLimit:Number(f.get('companyLimit')),requestLimit:Number(f.get('requestLimit'))});message='배치를 만들었습니다. 시작 버튼으로 실행할 수 있습니다.';await load();}catch(err){message=err.message;render();}}},{signal:life.signal});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-bpd]');if(!b)return;const action=b.dataset.bpd;b.disabled=true;try{if(action==='next')offset+=30;else if(action==='previous')offset=Math.max(0,offset-30);else if(action!=='refresh'){const r=await request({action,id:b.dataset.id});message=r.message||'요청을 반영했습니다.';}await load();}catch(err){message=err.message;render();}},{signal:life.signal});void load();
 return {destroy(){life.abort();clearTimeout(timer);}};
}

const matchLabels={DESCRIPTION:'사업 설명',PRODUCT:'제품·공정',BUSINESS_SEGMENT:'사업부',END_MARKET:'적용 산업',GEOGRAPHY:'지역',DOMESTIC_EXPORT:'수출·내수',CUSTOMER:'고객'};
const importanceLabels={DISCLOSED_ITEM_SHARE:'해당 공시 항목 비중 확인',QUALITATIVE_CORE:'주력사업 정성 근거',PRODUCT_EVIDENCE:'관련 제품 근거',CONFIRM_SCOPE:'관련 범위 추가 확인'};
const scopeLabels={CONSOLIDATED:'연결',SEPARATE:'별도',UNSPECIFIED:'범위 미확인'};
const amountText=v=>typeof v==='string'&&/^[+-]?\d+(?:\.\d+)?$/.test(v)?v.replace(/\B(?=(\d{3})+(?!\d))/g,','):Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:2}):'금액 미확인';
export function businessSearchResults(data){
 const companies=data.items||[],groups=[...new Set(companies.flatMap(c=>c.matches.map(m=>matchLabels[m.dimension]||'기타')))];
 return `<p class="bp-note">${data.coverage?`색인 수록 ${esc(data.coverage.companies)}개 기업 · `:''}${esc(data.coverage?.scope||'저장된 사업 자료만 검색합니다.')}<br>${esc(data.notice||'')}</p><p class="business-result-count">기업 ${companies.length}개${groups.length?' · '+groups.map(esc).join(' / '):''}</p>${companies.map(c=>`<article class="business-result"><header><div><span class="business-market">${c.market==='KR'?'국내':'미국'} · ${esc(c.ticker)}</span><h2><a data-nav href="/stock/${esc(c.market)}/${encodeURIComponent(c.ticker)}?tab=company">${esc(c.name)}</a></h2></div><button type="button" data-business-compare="${esc(c.market+':'+c.ticker)}" data-name="${esc(c.name)}">비교에 추가</button></header>${c.businessSummary?`<p class="business-summary">${esc(c.businessSummary.slice(0,350))}</p>`:''}<ul class="business-matches">${c.matches.filter(m=>m.dimension!=='DESCRIPTION').slice(0,6).map(m=>{const url=safeComparisonUrl(m.url);return `<li><div><span class="business-dimension">${esc(matchLabels[m.dimension]||'분류 미확인')}</span><strong>${esc(m.label)}</strong>${m.parent&&m.parent!==m.label?`<small>${esc(m.parent)}</small>`:''}</div><p>${esc(amountText(m.amountExact??m.amount))}${m.unit?' '+esc(m.unit):''} · <strong>${Number.isFinite(m.percent)?esc(m.percent.toLocaleString('ko-KR',{maximumFractionDigits:2}))+'%':'비중 미확인'}</strong></p><small>${esc(m.period?.label||m.period?.end||'기간 미확인')} · ${esc(scopeLabels[m.scope]||'범위 미확인')} · ${esc(importanceLabels[m.importance]||'추가 확인 필요')}</small><details><summary>매출 범위와 근거</summary><p>${esc(m.denominatorLabel||'분모 범위 미확인')} · ${m.shareOrigin==='DERIVED'?'공시 금액으로 계산한 비중':'공시 항목 값'}</p><blockquote>${esc(m.quote||'근거 문장 미확인')}</blockquote>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">근거 원문 ↗</a>`:''}<p class="bp-note">${m.locator?'근거 위치: '+esc(m.locator):'정확한 페이지 미확보 · 원문에서 '+esc(m.label)+' 검색'}</p></details></li>`;}).join('')}</ul><a data-nav class="business-detail-link" href="/stock/${esc(c.market)}/${encodeURIComponent(c.ticker)}?tab=company">사업·실적 상세 보기 →</a></article>`).join('')||'<div class="business-empty"><h2>저장된 근거에서 일치하는 기업을 찾지 못했습니다.</h2><p>다른 제품명이나 원문 표현으로 검색해 보세요. 미수록 기업에 사업이 없다는 뜻은 아닙니다.</p></div>'}`;
}
export function mountBusinessDirectory(root){
 if(new URLSearchParams(location.search).get('admin')==='1')return mountBusinessAdmin(root);
 const life=new AbortController();let pending=null,generation=0,selectedKey='';const initial=new URLSearchParams(location.search);
 root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">BUSINESS EXPLORER</div><h1>사업으로 기업 찾기</h1><p>저장된 공시의 제품·사업을 찾아 상세 화면과 기업 비교로 이어갑니다.</p></div><a data-nav href="/compare">기업 비교 →</a></div><section class="surface business-explorer"><form class="bp-search-form"><label>사업·제품 검색<input name="q" aria-label="사업·제품 검색" placeholder="제품명 또는 사업명" maxlength="100" required value="${esc(initial.get('q')||'')}"></label><label>시장<select name="market"><option value="">국내·미국</option><option value="KR">국내</option><option value="US">미국</option></select></label><label>항목 범위<select name="dimension"><option value="">전체 항목</option>${Object.entries(matchLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>확인된 최소 비중 (%)<input name="minShare" type="number" min="0" max="100" step="0.01" placeholder="조건 없음" value="${esc(initial.get('minShare')||'')}"></label><button type="submit">검색</button></form><p class="bp-note">비중 미확인은 0%가 아닙니다. 숫자 필터는 기간·분모·범위가 확인된 공시 항목에만 적용됩니다.</p><div class="bp-search-results" aria-live="polite"><p>제품명·사업명을 입력해 주세요. 새 AI 분석이나 외부 검색을 실행하지 않습니다.</p></div></section>`;
 const newsHost=document.createElement('section');root.querySelector('.business-explorer').before(newsHost);const newsView=mountNewsCompanies(newsHost);
 const form=root.querySelector('.bp-search-form'),target=root.querySelector('.bp-search-results');for(const name of ['market','dimension']){const input=form.elements[name];if([...input.options].some(o=>o.value===initial.get(name)))input.value=initial.get(name);}
 async function load(){const params=new URLSearchParams(new FormData(form));if(!params.get('q')?.trim())return;pending?.abort();pending=new AbortController();const current=++generation,key=params.toString();selectedKey=key;const urlParams=new URLSearchParams(params),analysisId=new URLSearchParams(location.search).get('newsAnalysis');if(analysisId)urlParams.set('newsAnalysis',analysisId);history.replaceState(history.state,'','/business?'+urlParams);target.innerHTML='<p role="status">저장된 사업 정보를 검색하고 있습니다.</p>';
  try{const response=await fetch('/api/business-profiles/search?'+key,{signal:AbortSignal.any([life.signal,pending.signal])});if(!response.ok)throw Error('검색 요청에 실패했습니다.');const result=await response.json();if(life.signal.aborted||current!==generation||key!==selectedKey)return;target.innerHTML=businessSearchResults(result);}
  catch(error){if(life.signal.aborted||current!==generation||error.name==='AbortError')return;target.innerHTML='<p role="alert">저장된 검색 자료를 불러오지 못했습니다.</p><button type="button" data-business-retry>다시 시도</button>';}
 }
 form.addEventListener('submit',e=>{e.preventDefault();void load();},{signal:life.signal});
 root.addEventListener('click',e=>{const button=e.target.closest('[data-business-compare]');if(button){const [market,ticker]=button.dataset.businessCompare.split(':');dispatchEvent(new CustomEvent('moa-compare-add',{detail:{key:button.dataset.businessCompare,market,ticker,name:button.dataset.name}}));}if(e.target.closest('[data-business-retry]'))void load();},{signal:life.signal});
 if(initial.get('q'))void load();
 return {destroy(){newsView.destroy();++generation;life.abort();pending?.abort();}};
}
